input.command:
cd /Users/jonasstenglein/.claude/jobs/064ce75e/tmp && for f in status/*.json; do echo "== $f"; python3 -c "
import json,sys
try: d=json.load(open('$f'))
except Exception as e: print('ERR',open('$f').read()[:300]); sys.exit()
r=d.get('run',d)
print({k:v for k,v in r.items() if not isinstance(v,(dict,list))})
for k in ('result','score','breakdown','platform'):
  if k in r: print(k, json.dumps(r[k])[:1500])
"; done

